class ModelNew(torch.nn.Module):
    """
    Optimized model: use custom AscendC kernel to fuse add + HardSwish gating after ConvTranspose3d.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = torch.nn.ConvTranspose3d(in_channels, out_channels, kernel_size,
                                                       stride=stride, padding=padding, output_padding=output_padding)
        # bias_shape kept for API compatibility with original model, but not needed here.

    def forward(self, x, add_input):
        x = self.conv_transpose(x)
        # Fused: y = (x + add_input) * hardswish(x + add_input)
        return custom_ops_lib.conv_transpose3d_add_hard_swish_custom(x, add_input)
